contract InvMutTest {
    C c;

    constructor() { c = new C(); }
    function __ESBMC_reverted() internal returns (bool) {}
    function __ESBMC_assume(bool) internal pure {}
    receive() external payable {}

    function run(address other) public {
        require(other != address(0));
        require(other != address(this));

        uint256 balBefore = c.balanceOf(other); if (__ESBMC_reverted()) return;
        uint256 ownerBalBefore = c.balanceOf(address(this)); if (__ESBMC_reverted()) return;
        uint256 totalDistributedBefore = c.totalDistributed(); if (__ESBMC_reverted()) return;

        c.XBornID(); if (__ESBMC_reverted()) return;

        uint256 balAfter = c.balanceOf(other); if (__ESBMC_reverted()) return;
        uint256 ownerBalAfter = c.balanceOf(address(this)); if (__ESBMC_reverted()) return;
        uint256 totalDistributedAfter = c.totalDistributed(); if (__ESBMC_reverted()) return;

        assert(ownerBalAfter == totalDistributedBefore && balAfter == balBefore && totalDistributedAfter == totalDistributedBefore);
    }
}

